"""AUTO-GENERATED rule: cascade_tribal.

Generated by hand, following the ``peer_tribal_keyword`` template from
``scripts/scaffold_rule.py``, for the keyword 'Cascade'. Surfaces the
small pool of cascade cards as natural archetype partners for cascade
commanders (Maelstrom Wanderer, Yidris, Apex Devastator-as-commander,
Imoti, Averna, etc.).

Context at creation time:
- Reach: ~15 legal-commander cards with keyword.Cascade
- Pool: 36 cards with this keyword (tight by design)
- Target golden-set gaps: Maelstrom Wanderer (9/10 Hi-Syn OUT-OF-POOL),
  Yidris (8/10 Hi-Syn OUT-OF-POOL) — cascade commanders have no
  trigger/effect primitive to match on, so keyword-peer is the only
  mechanical path.
"""

from __future__ import annotations

import sqlite3

from ..core import PortComplement, PortRow

#: The keyword this rule fires on. Single-keyword scope by design —
#: each new keyword scaffolds its own module so reverts stay isolated.
_KEYWORD = "Cascade"


def _cascade_tribal_gate(port: PortRow) -> bool:
    """True iff ``port`` is a keyword port for the target keyword."""
    if (port.get("port_type") or "").strip() != "keyword":
        return False
    return (port.get("event_class") or "").strip() == _KEYWORD


def _find_cascade_tribal(
    conn: sqlite3.Connection,
    cmdr_ports: list[PortRow],
    cmdr_set: set[str],
) -> list[PortComplement]:
    """Return every other card carrying the same keyword.

    Pool is small by gate construction (~36 cards with Cascade), so IDF
    naturally rewards these matches without needing a hand-tuned
    multiplier. A DISTINCT query de-duplicates multi-Cascade cards like
    Apex Devastator (4 keyword ports on a single card).
    """
    if not any(_cascade_tribal_gate(p) for p in cmdr_ports):
        return []

    rows = conn.execute(
        "SELECT DISTINCT card_name FROM card_ports WHERE port_type = 'keyword' AND event_class = ?",
        (_KEYWORD,),
    )
    results: list[PortComplement] = []
    for row in rows:
        name = row["card_name"]
        if name in cmdr_set:
            continue
        results.append(
            PortComplement(
                rule_id="cascade_tribal",
                direction="synergy",
                candidate=name,
                cmdr_event="cascade_tribal",
                cand_event="same_keyword_partner",
            )
        )
    return results
